CREATE TRIGGER storage_approved_workflow_runs_insert AFTER INSERT ON approved_workflow_runs BEGIN
 INSERT OR IGNORE INTO workspace_storage_accounts(workspace_id) VALUES(NEW.workspace_id);
 SELECT CASE WHEN (COALESCE(length(CAST(NEW."result_json" AS BLOB)),0)+COALESCE(length(CAST(NEW."lease_token" AS BLOB)),0))>0 AND EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=NEW.workspace_id AND records_bytes+(COALESCE(length(CAST(NEW."result_json" AS BLOB)),0)+COALESCE(length(CAST(NEW."lease_token" AS BLOB)),0))>(CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_records_limit ELSE included_records_limit END)) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
 UPDATE workspace_storage_accounts SET records_bytes=records_bytes+(COALESCE(length(CAST(NEW."result_json" AS BLOB)),0)+COALESCE(length(CAST(NEW."lease_token" AS BLOB)),0)) WHERE workspace_id=NEW.workspace_id;
END;
CREATE TRIGGER storage_approved_workflow_runs_update AFTER UPDATE ON approved_workflow_runs BEGIN
 SELECT CASE WHEN NEW.workspace_id IS NOT OLD.workspace_id THEN RAISE(ABORT,'WORKSPACE_STORAGE_SCOPE_IMMUTABLE') END;
 SELECT CASE WHEN NOT(0) AND (COALESCE(length(CAST(NEW."result_json" AS BLOB)),0)+COALESCE(length(CAST(NEW."lease_token" AS BLOB)),0))>(COALESCE(length(CAST(OLD."result_json" AS BLOB)),0)+COALESCE(length(CAST(OLD."lease_token" AS BLOB)),0)) AND EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=NEW.workspace_id AND records_bytes+(COALESCE(length(CAST(NEW."result_json" AS BLOB)),0)+COALESCE(length(CAST(NEW."lease_token" AS BLOB)),0))-(COALESCE(length(CAST(OLD."result_json" AS BLOB)),0)+COALESCE(length(CAST(OLD."lease_token" AS BLOB)),0))>(CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_records_limit ELSE included_records_limit END)) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
 UPDATE workspace_storage_accounts SET records_bytes=records_bytes+(COALESCE(length(CAST(NEW."result_json" AS BLOB)),0)+COALESCE(length(CAST(NEW."lease_token" AS BLOB)),0))-(COALESCE(length(CAST(OLD."result_json" AS BLOB)),0)+COALESCE(length(CAST(OLD."lease_token" AS BLOB)),0)) WHERE workspace_id=NEW.workspace_id;
END;
CREATE TRIGGER storage_approved_workflow_runs_delete AFTER DELETE ON approved_workflow_runs BEGIN
 UPDATE workspace_storage_accounts SET records_bytes=records_bytes-(COALESCE(length(CAST(OLD."result_json" AS BLOB)),0)+COALESCE(length(CAST(OLD."lease_token" AS BLOB)),0)) WHERE workspace_id=OLD.workspace_id;
END;

