 SELECT CASE WHEN NOT(0) AND (COALESCE(length(CAST(NEW."normalized_domain" AS BLOB)),0)+COALESCE(length(CAST(NEW."company_name" AS BLOB)),0)+COALESCE(length(CAST(NEW."website" AS BLOB)),0)+COALESCE(length(CAST(NEW."country" AS BLOB)),0)+COALESCE(length(CAST(NEW."industry" AS BLOB)),0)+COALESCE(length(CAST(NEW."confidence" AS BLOB)),0)+COALESCE(length(CAST(NEW."source" AS BLOB)),0)+COALESCE(length(CAST(NEW."customer_since" AS BLOB)),0))>(COALESCE(length(CAST(OLD."normalized_domain" AS BLOB)),0)+COALESCE(length(CAST(OLD."company_name" AS BLOB)),0)+COALESCE(length(CAST(OLD."website" AS BLOB)),0)+COALESCE(length(CAST(OLD."country" AS BLOB)),0)+COALESCE(length(CAST(OLD."industry" AS BLOB)),0)+COALESCE(length(CAST(OLD."confidence" AS BLOB)),0)+COALESCE(length(CAST(OLD."source" AS BLOB)),0)+COALESCE(length(CAST(OLD."customer_since" AS BLOB)),0)) AND EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=NEW.workspace_id AND records_bytes+(COALESCE(length(CAST(NEW."normalized_domain" AS BLOB)),0)+COALESCE(length(CAST(NEW."company_name" AS BLOB)),0)+COALESCE(length(CAST(NEW."website" AS BLOB)),0)+COALESCE(length(CAST(NEW."country" AS BLOB)),0)+COALESCE(length(CAST(NEW."industry" AS BLOB)),0)+COALESCE(length(CAST(NEW."confidence" AS BLOB)),0)+COALESCE(length(CAST(NEW."source" AS BLOB)),0)+COALESCE(length(CAST(NEW."customer_since" AS BLOB)),0))-(COALESCE(length(CAST(OLD."normalized_domain" AS BLOB)),0)+COALESCE(length(CAST(OLD."company_name" AS BLOB)),0)+COALESCE(length(CAST(OLD."website" AS BLOB)),0)+COALESCE(length(CAST(OLD."country" AS BLOB)),0)+COALESCE(length(CAST(OLD."industry" AS BLOB)),0)+COALESCE(length(CAST(OLD."confidence" AS BLOB)),0)+COALESCE(length(CAST(OLD."source" AS BLOB)),0)+COALESCE(length(CAST(OLD."customer_since" AS BLOB)),0))>(CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_records_limit ELSE included_records_limit END)) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
