CREATE TRIGGER storage_customer_brand_asset_chunks_insert AFTER INSERT ON customer_brand_asset_chunks BEGIN
 INSERT OR IGNORE INTO workspace_storage_accounts(workspace_id) VALUES((SELECT workspace_id FROM customer_brand_assets WHERE id=NEW.asset_id));
 SELECT CASE WHEN (length(NEW.chunk_data))>0 AND EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=(SELECT workspace_id FROM customer_brand_assets WHERE id=NEW.asset_id) AND files_bytes+(length(NEW.chunk_data))>(CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_files_limit ELSE included_files_limit END)) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
 UPDATE workspace_storage_accounts SET files_bytes=files_bytes+(length(NEW.chunk_data)) WHERE workspace_id=(SELECT workspace_id FROM customer_brand_assets WHERE id=NEW.asset_id);
END;
CREATE TRIGGER storage_customer_brand_asset_chunks_update AFTER UPDATE ON customer_brand_asset_chunks BEGIN
 SELECT CASE WHEN (SELECT workspace_id FROM customer_brand_assets WHERE id=NEW.asset_id) IS NOT (SELECT workspace_id FROM customer_brand_assets WHERE id=OLD.asset_id) THEN RAISE(ABORT,'WORKSPACE_STORAGE_SCOPE_IMMUTABLE') END;
 SELECT CASE WHEN NOT(0) AND (length(NEW.chunk_data))>(length(OLD.chunk_data)) AND EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=(SELECT workspace_id FROM customer_brand_assets WHERE id=NEW.asset_id) AND files_bytes+(length(NEW.chunk_data))-(length(OLD.chunk_data))>(CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_files_limit ELSE included_files_limit END)) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
 UPDATE workspace_storage_accounts SET files_bytes=files_bytes+(length(NEW.chunk_data))-(length(OLD.chunk_data)) WHERE workspace_id=(SELECT workspace_id FROM customer_brand_assets WHERE id=NEW.asset_id);
END;
CREATE TRIGGER storage_customer_brand_asset_chunks_delete AFTER DELETE ON customer_brand_asset_chunks BEGIN
 UPDATE workspace_storage_accounts SET files_bytes=files_bytes-(length(OLD.chunk_data)) WHERE workspace_id=(SELECT workspace_id FROM customer_brand_assets WHERE id=OLD.asset_id);
END;

