END;
CREATE TRIGGER storage_customer_brand_assets_update AFTER UPDATE ON customer_brand_assets BEGIN
 SELECT CASE WHEN NEW.workspace_id IS NOT OLD.workspace_id THEN RAISE(ABORT,'WORKSPACE_STORAGE_SCOPE_IMMUTABLE') END;
 SELECT CASE WHEN NOT(0) AND (COALESCE(length(CAST(NEW."validation" AS BLOB)),0)+COALESCE(length(CAST(NEW."mime_type" AS BLOB)),0)+COALESCE(length(CAST(NEW."content_sha256" AS BLOB)),0))>(COALESCE(length(CAST(OLD."validation" AS BLOB)),0)+COALESCE(length(CAST(OLD."mime_type" AS BLOB)),0)+COALESCE(length(CAST(OLD."content_sha256" AS BLOB)),0)) AND EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=NEW.workspace_id AND records_bytes+(COALESCE(length(CAST(NEW."validation" AS BLOB)),0)+COALESCE(length(CAST(NEW."mime_type" AS BLOB)),0)+COALESCE(length(CAST(NEW."content_sha256" AS BLOB)),0))-(COALESCE(length(CAST(OLD."validation" AS BLOB)),0)+COALESCE(length(CAST(OLD."mime_type" AS BLOB)),0)+COALESCE(length(CAST(OLD."content_sha256" AS BLOB)),0))>(CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_records_limit ELSE included_records_limit END)) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
 UPDATE workspace_storage_accounts SET records_bytes=records_bytes+(COALESCE(length(CAST(NEW."validation" AS BLOB)),0)+COALESCE(length(CAST(NEW."mime_type" AS BLOB)),0)+COALESCE(length(CAST(NEW."content_sha256" AS BLOB)),0))-(COALESCE(length(CAST(OLD."validation" AS BLOB)),0)+COALESCE(length(CAST(OLD."mime_type" AS BLOB)),0)+COALESCE(length(CAST(OLD."content_sha256" AS BLOB)),0)) WHERE workspace_id=NEW.workspace_id;
