CREATE TRIGGER storage_customer_project_state_insert AFTER INSERT ON customer_project_state BEGIN
 INSERT OR IGNORE INTO workspace_storage_accounts(workspace_id) VALUES((SELECT workspace_id FROM customer_projects WHERE id=NEW.project_id));
 SELECT CASE WHEN (COALESCE(length(CAST(NEW."payload_json" AS BLOB)),0))>0 AND EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=(SELECT workspace_id FROM customer_projects WHERE id=NEW.project_id) AND records_bytes+(COALESCE(length(CAST(NEW."payload_json" AS BLOB)),0))>(CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_records_limit ELSE included_records_limit END)) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
 UPDATE workspace_storage_accounts SET records_bytes=records_bytes+(COALESCE(length(CAST(NEW."payload_json" AS BLOB)),0)) WHERE workspace_id=(SELECT workspace_id FROM customer_projects WHERE id=NEW.project_id);
END;
