 SELECT CASE WHEN NOT(0) AND (COALESCE(length(CAST(NEW."fingerprint" AS BLOB)),0)+COALESCE(length(CAST(NEW."source_url" AS BLOB)),0)+COALESCE(length(CAST(NEW."source_type" AS BLOB)),0)+COALESCE(length(CAST(NEW."title" AS BLOB)),0)+COALESCE(length(CAST(NEW."excerpt" AS BLOB)),0)+COALESCE(length(CAST(NEW."signal_ids_json" AS BLOB)),0))>(COALESCE(length(CAST(OLD."fingerprint" AS BLOB)),0)+COALESCE(length(CAST(OLD."source_url" AS BLOB)),0)+COALESCE(length(CAST(OLD."source_type" AS BLOB)),0)+COALESCE(length(CAST(OLD."title" AS BLOB)),0)+COALESCE(length(CAST(OLD."excerpt" AS BLOB)),0)+COALESCE(length(CAST(OLD."signal_ids_json" AS BLOB)),0)) AND EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=NEW.workspace_id AND records_bytes+(COALESCE(length(CAST(NEW."fingerprint" AS BLOB)),0)+COALESCE(length(CAST(NEW."source_url" AS BLOB)),0)+COALESCE(length(CAST(NEW."source_type" AS BLOB)),0)+COALESCE(length(CAST(NEW."title" AS BLOB)),0)+COALESCE(length(CAST(NEW."excerpt" AS BLOB)),0)+COALESCE(length(CAST(NEW."signal_ids_json" AS BLOB)),0))-(COALESCE(length(CAST(OLD."fingerprint" AS BLOB)),0)+COALESCE(length(CAST(OLD."source_url" AS BLOB)),0)+COALESCE(length(CAST(OLD."source_type" AS BLOB)),0)+COALESCE(length(CAST(OLD."title" AS BLOB)),0)+COALESCE(length(CAST(OLD."excerpt" AS BLOB)),0)+COALESCE(length(CAST(OLD."signal_ids_json" AS BLOB)),0))>(CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_records_limit ELSE included_records_limit END)) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
