CREATE TRIGGER storage_opportunity_signals_insert AFTER INSERT ON opportunity_signals BEGIN
 INSERT OR IGNORE INTO workspace_storage_accounts(workspace_id) VALUES((SELECT workspace_id FROM opportunities WHERE id=NEW.opportunity_id));
 SELECT CASE WHEN (0)>0 AND EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=(SELECT workspace_id FROM opportunities WHERE id=NEW.opportunity_id) AND records_bytes+(0)>(CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_records_limit ELSE included_records_limit END)) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
 UPDATE workspace_storage_accounts SET records_bytes=records_bytes+(0) WHERE workspace_id=(SELECT workspace_id FROM opportunities WHERE id=NEW.opportunity_id);
END;
CREATE TRIGGER storage_opportunity_signals_update AFTER UPDATE ON opportunity_signals BEGIN
 SELECT CASE WHEN (SELECT workspace_id FROM opportunities WHERE id=NEW.opportunity_id) IS NOT (SELECT workspace_id FROM opportunities WHERE id=OLD.opportunity_id) THEN RAISE(ABORT,'WORKSPACE_STORAGE_SCOPE_IMMUTABLE') END;
 SELECT CASE WHEN NOT(0) AND (0)>(0) AND EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=(SELECT workspace_id FROM opportunities WHERE id=NEW.opportunity_id) AND records_bytes+(0)-(0)>(CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_records_limit ELSE included_records_limit END)) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
 UPDATE workspace_storage_accounts SET records_bytes=records_bytes+(0)-(0) WHERE workspace_id=(SELECT workspace_id FROM opportunities WHERE id=NEW.opportunity_id);
END;
