CREATE TRIGGER storage_workspace_storage_objects_insert AFTER INSERT ON workspace_storage_objects BEGIN
 INSERT OR IGNORE INTO workspace_storage_accounts(workspace_id) VALUES(NEW.workspace_id);
 SELECT CASE WHEN (NEW.byte_size)>0 AND EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=NEW.workspace_id AND files_bytes+(NEW.byte_size)>(CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_files_limit ELSE included_files_limit END)) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
 UPDATE workspace_storage_accounts SET files_bytes=files_bytes+(NEW.byte_size) WHERE workspace_id=NEW.workspace_id;
END;
CREATE TRIGGER storage_workspace_storage_objects_update AFTER UPDATE ON workspace_storage_objects BEGIN
 SELECT CASE WHEN NEW.workspace_id IS NOT OLD.workspace_id THEN RAISE(ABORT,'WORKSPACE_STORAGE_SCOPE_IMMUTABLE') END;
 SELECT CASE WHEN NOT(NEW.state='ready' AND OLD.state='unmeasured') AND (NEW.byte_size)>(OLD.byte_size) AND EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=NEW.workspace_id AND files_bytes+(NEW.byte_size)-(OLD.byte_size)>(CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_files_limit ELSE included_files_limit END)) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
 UPDATE workspace_storage_accounts SET files_bytes=files_bytes+(NEW.byte_size)-(OLD.byte_size) WHERE workspace_id=NEW.workspace_id;
END;
CREATE TRIGGER storage_workspace_storage_objects_delete AFTER DELETE ON workspace_storage_objects BEGIN
 UPDATE workspace_storage_accounts SET files_bytes=files_bytes-(OLD.byte_size) WHERE workspace_id=OLD.workspace_id;
END;

CREATE TRIGGER storage_customer_projects_customer_project_state_cascade BEFORE DELETE ON customer_projects BEGIN DELETE FROM customer_project_state WHERE project_id=OLD.id; END;

CREATE TRIGGER storage_writing_reference_sources_writing_reference_chunks_cascade BEFORE DELETE ON writing_reference_sources BEGIN DELETE FROM writing_reference_chunks WHERE source_id=OLD.id; END;

CREATE TRIGGER storage_research_runs_run_events_cascade BEFORE DELETE ON research_runs BEGIN DELETE FROM run_events WHERE run_id=OLD.id; END;

CREATE TRIGGER storage_opportunities_opportunity_signals_cascade BEFORE DELETE ON opportunities BEGIN DELETE FROM opportunity_signals WHERE opportunity_id=OLD.id; END;

CREATE TRIGGER storage_customer_brand_assets_customer_brand_asset_chunks_cascade BEFORE DELETE ON customer_brand_assets BEGIN DELETE FROM customer_brand_asset_chunks WHERE asset_id=OLD.id; END;
